# PTX source for 1‑D average pooling on fp16 tensors (sm_80)
PTX_SOURCE = r'''
.version 7.1
.target sm_80
.address_size 64

.visible .entry avgpool1d_fp16(
    .param .u64 x_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 C,
    .param .u32 L,
    .param .u32 KSIZE,
    .param .u32 STRIDE,
    .param .u32 PAD
)
{
    // ---------- registers ----------
    .reg .pred   %p<6>;
    .reg .b64    %rd<15>;
    .reg .b32    %r<20>;
    .reg .s32    %s<12>;
    .reg .f32    %f<4>;
    .reg .f16    %h<2>;

    // ---------- thread identifiers ----------
    mov.u32    %r0, %tid.x;          // threadIdx.x
    mov.u32    %r1, %ctaid.x;        // blockIdx.x
    mov.u32    %r2, %ntid.x;         // blockDim.x
    mad.lo.s32 %r3, %r1, %r2, %r0;   // linear thread id = blockIdx.x*blockDim.x + threadIdx.x

    // ---------- load kernel parameters ----------
    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [y_ptr];
    ld.param.u32 %r4,  [N];
    ld.param.u32 %r5,  [C];
    ld.param.u32 %r6,  [L];
    ld.param.u32 %r7,  [KSIZE];
    ld.param.u32 %r8,  [STRIDE];
    ld.param.u32 %r9,  [PAD];

    // ---------- compute output length ----------
    // L_out = (L + 2*PAD - KSIZE) / STRIDE + 1
    mul.lo.u32 %r10, %r9, 2;          // 2*PAD
    add.u32    %r10, %r6, %r10;       // L + 2*PAD
    sub.u32    %r10, %r10, %r7;       // -KSIZE
    div.u32    %r10, %r10, %r8;       // /STRIDE
    add.u32    %r10, %r10, 1;         // +1  --> L_out in %r10

    // ---------- total number of output elements ----------
    mul.lo.u32 %r11, %r4, %r5;        // N*C
    mul.lo.u32 %r12, %r11, %r10;      // N*C*L_out

    // if thread id >= total, exit
    setp.ge.u32 %p0, %r3, %r12;
    @%p0 bra DONE;

    // ---------- decompose linear id ----------
    // n = id / (C*L_out)
    mul.lo.u32 %r13, %r5, %r10;       // C*L_out
    div.u32    %r14, %r3, %r13;       // n
    rem.u32    %r15, %r3, %r13;       // rem = c*L_out + out_idx
    div.u32    %r16, %r15, %r10;      // c
    rem.u32    %r17, %r15, %r10;      // out_idx

    // ---------- compute first input index (with padding) ----------
    // src = out_idx*STRIDE - PAD   (signed)
    mul.lo.u32 %s0, %r17, %r8;        // out_idx*STRIDE
    sub.s32    %s0, %s0, %r9;         // -PAD   --> signed %s0

    // ---------- accumulator (float) ----------
    mov.f32 %f0, 0.0;

    // ---------- loop over kernel window ----------
    .reg .u32 %k;
    mov.u32 %k, 0;
LOOP_K:
    setp.ge.u32 %p1, %k, %r7;        // k >= KSIZE ?
    @%p1 bra END_LOOP_K;

    // pos = src + k   (signed)
    add.s32 %s1, %s0, %k;

    // if pos < 0   skip
    setp.lt.s32 %p2, %s1, 0;
    @%p2 bra SKIP_K;

    // if pos >= L   skip
    setp.ge.s32 %p3, %s1, %r6;
    @%p3 bra SKIP_K;

    // ---------- compute flat input index ----------
    // idx = ((n*C + c)*L + pos)
    mul.lo.u32 %r18, %r14, %r5;       // n*C
    add.u32    %r18, %r18, %r16;      // n*C + c
    mul.lo.u32 %r19, %r18, %r6;       // (n*C + c)*L
    add.s32    %r19, %r19, %s1;       // + pos   (still fits in 32‑bit)

    // address = x_ptr + idx*2 (half = 2 bytes)
    cvt.u64.u32 %rd3, %r19;
    shl.b64    %rd3, %rd3, 1;         // *2
    add.u64    %rd4, %rd1, %rd3;      // final address

    // load half, convert to float, accumulate
    ld.global.f16 %h0, [%rd4];
    cvt.f32.f16 %f1, %h0;
    add.f32 %f0, %f0, %f1;

SKIP_K:
    add.u32 %k, %k, 1;
    bra LOOP_K;

END_LOOP_K:
    // ---------- divide by KSIZE ----------
    cvt.f32.u32 %f2, %r7;            // KSIZE as float
    div.f32 %f3, %f0, %f2;           // average

    // ---------- store result (as half) ----------
    // out_idx linear address: ((n*C + c)*L_out + out_idx)
    mul.lo.u32 %r20, %r14, %r5;       // n*C
    add.u32    %r20, %r20, %r16;      // n*C + c
    mul.lo.u32 %r21, %r20, %r10;      // (n*C + c)*L_out
    add.u32    %r21, %r21, %r17;      // + out_idx
    cvt.u64.u32 %rd5, %r21;
    shl.b64    %rd5, %rd5, 1;         // *2 (bytes)
    add.u64    %rd6, %rd2, %rd5;      // output address

    cvt.f16.f32 %h1, %f3;
    st.global.f16 [%rd6], %h1;

DONE:
    ret;
}
'''

# ----------------------------------------------------------------------
# Python wrapper that loads the PTX and launches the kernel.
# The harness provides `ptx_load` and `ptx_launch`.
# ----------------------------------------------------------------------
class ModelNew:
    def __init__(self, kernel_size: int, stride: int = 1, padding: int = 0):
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        # load PTX module
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x):
        # x is a torch.cuda.FloatTensor (fp16)
        n, c, l = x.shape
        out_len = (l + 2 * self.padding - self.kernel_size) // self.stride + 1
        y = torch.empty(n, c, out_len, dtype=torch.float16, device='cuda')

        # launch configuration (256 threads per block)
        threads_per_block = 256
        total_threads = n * c * out_len
        blocks = (total_threads + threads_per_block - 1) // threads_per_block

        # arguments to the kernel
        args = [
            x.data_ptr(),
            y.data_ptr(),
            n,
            c,
            l,
            self.kernel_size,
            self.stride,
            self.padding
        ]

        # launch the kernel
        ptx_launch(self.module, "avgpool1d_fp16", (blocks,), (threads_per_block,), args)

        return y
